evidence.command:
npm run smoke; if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$home = Invoke-WebRequest -Uri 'http://127.0.0.1:4173/' -UseBasicParsing -TimeoutSec 15
Write-Output "preview GET / status=$($home.StatusCode) bytes=$($home.RawContentLength)"
if ($home.StatusCode -ne 200) { exit 1 }
$missing = @()
foreach ($id in @('todo-form','new-todo','add-btn','todo-list','empty-state','stats','stats-total','stats-completed','new-priority','priority-filter','filter-summary')) { if ($home.Content -notmatch ('id="' + [regex]::Escape($id) + '"')) { $missing += $id } }
if ($missing.Count -gt 0) { Write-Output "missing mounts: $($missing -join ',')"; exit 1 }
Write-Output "preview URL 含全部 11 个挂载点"
$again = Invoke-WebRequest -Uri 'http://127.0.0.1:4173/' -UseBasicParsing -TimeoutSec 15
if ($again.Content -ne $home.Content) { Write-Output 'repeat response differs'; exit 1 }
Write-Output "RUN_STEP_PASSED http://127.0.0.1:4173/"

npm run smoke; if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$page = Invoke-WebRequest -Uri 'http://127.0.0.1:4173/' -UseBasicParsing -TimeoutSec 15
