if ($missing.Count -gt 0) { Write-Output "missing mounts: $($missing -join ',')"; exit 1 }
Write-Output "preview URL 含全部 11 个挂载点"
$againPage = Invoke-WebRequest -Uri 'http://127.0.0.1:4173/' -UseBasicParsing -TimeoutSec 15
if ($againPage.Content -ne $page.Content) { Write-Output 'repeat response differs'; exit 1 }
$css = Invoke-WebRequest -Uri 'http://127.0.0.1:4173/styles.css' -UseBasicParsing -TimeoutSec 15
Write-Output "preview GET /styles.css status=$($css.StatusCode) bytes=$($css.RawContentLength)"
if ($css.StatusCode -ne 200) { exit 1 }
Write-Output "RUN_STEP_PASSED http://127.0.0.1:4173/"
